var t=`0247-saganaki`;var n=`world-0247`;var a=`GR`;var o=`southern-europe`;var s=4;var l=10;var r={en:`Saganaki`,ua:`Саганакі`};var u={en:`A traditional Greece dish made with halloumi, all-purpose flour, lemon juice. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: халумі, пшеничне борошно універсальне, лимонний сік. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:3,i:[[`halloumi`,420,`g`],[`all-purpose-flour`,60,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 6 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 6 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:6,i:[[`extra-virgin-olive-oil`,40,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:1,i:[[`lemon-juice`,30,`ml`],[`ground-black-pepper`,null,`to_taste`]]}];var h={slug:t,id:n,country:`GR`,region:o,servings:4,minutes:10,title:r,text:u,steps:d};export{a as country,h as default,n as id,l as minutes,o as region,s as servings,t as slug,d as steps,u as text,r as title};